"""Reviewed figure plan, exact input paths and English caption drafts."""
V='verification/'
R='results/'
B='pfpd_baqp_finite_domain_boundary_consistency_v1/'
A='pfpd_at1_activation_root_cause_and_fix_v1/'
C5='pfpd_at1_c5_stability_v1/'
C7='pfpd_at1_c7_early_branch_v1/'
ONSET=V+C7+'activation/C5_C7_COMPARISON.json'
S5=V+C5+'SUMMARY.json'
S7=V+C7+'branch/ALL.json'
BS=[V+B+x+'/SUMMARY.json' for x in ('C5','C7','L050','L075')]
SPECS=[
 dict(id='fig01',slug='research_evidence_overview',title='From bond activation to interpretable clot mechanics',message='Observed activation, numerical admissibility and physical interpretation are separate claims.',sources=[ONSET,S5,S7,V+B+'SUMMARY.json'],plot_type='Evidence-linked schematic',clot_relevance='Places current coupon evidence in the future clot-model validation chain.',caption='Evidence map for the current clot-model development candidate. Quantities are taken from archived C5/C7 activation and branch audits and the finite-domain BAQP audit. Arrows organize the research argument; they do not represent a validated causal or biological model. Neither bond activation nor a converged positive-phase state establishes macroscopic clot rupture.'),
 dict(id='fig02',slug='activation_onset_and_sampling',title='Activation shifts with discretization',message='The first set contains two bonds on both grids, while its fraction and onset strain change.',sources=[ONSET,V+'pfpd_at1_c5_activation_stationarity_audit_v1/activation/BRACKET.json',V+C7+'activation/BRACKET.json',*BS[:2]],plot_type='Onset intervals, bond fractions and normalized location',clot_relevance='A raw activated-bond fraction is not a mesh-independent failure measure.',caption='C5 and C7 activation is compared for the same corrected physical cube and frozen candidate model. Markers show the diagnostic weak-state strain, with numerical brackets shown as intervals rather than statistical confidence intervals; these intervals are smaller than the markers at this scale. Both first sets contain two bonds, so the smaller C7 fraction partly reflects its larger bond denominator. Activation remains boundary-associated, and two grids do not establish convergence or a crack prediction.'),
 dict(id='fig03',slug='preactivation_end_layer_concentration',title='End-layer concentration precedes activation',message='Similar end-layer displacement increments become larger local strain as spacing decreases.',sources=[V+A+'SUMMARY.json',V+A+'CONFIG.json',*[R+A+f'tables/{c}_FULL_CLAMP_BASELINE_0.0030_CENTERLINE_GAPS.csv' for c in ('C5','C7')],*[R+A+f'tables/{c}_FULL_CLAMP_BASELINE_0.0030_AXIAL_BONDS.csv' for c in ('C5','C7')]],plot_type='Saved centerline bond increments and loading-control comparison',clot_relevance='Identifies a mechanical precursor that must be separated from a clot-specific damage mechanism.',caption='Archived intact equilibria at engineering strain 0.003 show the end-layer displacement increment and the associated centerline bond strain. The affine reference is the prescribed engineering strain, while driver amplification is measured relative to the archived affine energy density. Releasing lateral clamp components does not reduce the recorded peak amplification. These observations support a boundary-sensitive mechanical precursor, but they do not prove a defective operator or identify a physical clot-failure mechanism.'),
 dict(id='fig04',slug='affine_layer_forces_and_cumulative_loading',title='Affine deformation requires distributed nodal forces',message='Exact affine kinematics does not imply equilibrium under surface-only constraints.',sources=[*[R+B+f'tables/{c}_layers.csv' for c in ('C5','C7')],*[R+B+f'tables/{c}_cumulative.csv' for c in ('C5','C7','L075')],*BS],plot_type='Signed layer forces and cumulative required force',clot_relevance='Shows why prescribed displacement and physically interpreted traction need separate validation.',caption='Signed internal layer forces are shown for the exact affine state, together with cumulative manufactured external force from the top boundary. All forces are normalized by the matching continuum reaction Pzz L squared. The cumulative L075 curve overshoots before approaching its final half-reaction, so a first threshold crossing is not a confinement thickness. Manufactured force is the negative of the computed internal force and is not an independently validated physical loading law.'),
 dict(id='fig05',slug='first_layer_force_origins',title='First-layer force contains several contributions',message='Z correction is larger, but neither a large term nor a signed endpoint contribution proves a bias.',sources=BS[:2]+[V+B+'NORMALIZATION_CHANNELS.json'],plot_type='Signed algebraic contribution bars',clot_relevance='Avoids treating a force-formula component as a physical damage mechanism.',caption='Exact algebraic decompositions of the bottom first-interior center-particle force separate direct and Z terms, loaded-surface versus other neighbors, and endpoint-normalization sources. Contributions are divided by the signed net axial force; negative values and values above unity represent cancellation. Z supplies approximately 78 to 82 percent of the net force, while the loaded-surface endpoint normalization is small. All components sum to the original model, and no alternative constitutive law or boundary correction is tested here.'),
 dict(id='fig06',slug='finite_domain_support_and_residuals',title='A full family does not isolate the force stencil',message='The geometric core gate fails; complete multi-hop force support is absent.',sources=[R+B+f'tables/{c}_particles.csv' for c in ('C5','L050','L075')]+BS+[V+B+'CONFIG.json'],plot_type='Particle force scatter and support counts',clot_relevance='A boundary-free mechanical oracle is needed before interpreting local activation as failure.',caption='Saved affine nodal force magnitudes are plotted against distance to the nearest surface for fixed spacing and horizon. Filled symbols distinguish particles with a geometrically complete family from particles whose family is truncated; the dashed distance marker denotes one horizon. L075 has 27 full-family particles, but its maximum core residual exceeds both declared patch-test criteria and it has no fully closed two- or three-hop core. This failed geometric test does not by itself establish a boundary-independent bulk defect.'),
 dict(id='fig07',slug='energy_virtual_work_and_half_reaction',title='Energy consistency and traction recovery differ',message='Global affine energy and virtual work agree while small-domain half-reactions differ.',sources=BS+[V+B+'VIRTUAL_WORK_TRACTION.json',V+B+'CONFIG.json'],plot_type='Energy error and reaction/virtual-work comparison',clot_relevance='Defines which loading consistency checks are prerequisites for interpretable clot response.',caption='Global affine energy errors are compared with the observed half-domain manufactured reaction and the affine virtual-work ratio. The energy and virtual work agree with their continuum references to floating-point accuracy, whereas C5 and C7 half-reactions differ by about 38 and 44 percent. Distributed forces act at different moment arms from surface traction, so energy agreement does not force their half-resultants to match. The one-percent reaction band is the archived audit criterion, not measurement uncertainty.'),
 dict(id='fig08',slug='positive_phase_branch',title='Positive phase does not establish rupture',message='C5 has audited stable states; C7 has accepted stationary states with stability unassessed.',sources=[ONSET,S5,S7,*[V+C5+f'states/S{i}/INPUT_VERIFICATION.json' for i in range(1,8)],*[V+C5+f'continuation/E{i:02}/SUMMARY.json' for i in range(1,7)]],plot_type='Maximum/weighted mean phase, stress and active counts',clot_relevance='Separates phase amplitude growth from spatial propagation and macroscopic rupture.',caption='Archived positive-phase states show maximum phase, energy-weighted mean phase, nominal reaction stress and active-bond counts. Phase and count curves use strain above each grid\'s diagnostic onset; stress uses absolute engineering strain. Filled C5 markers denote 13 audited stable positive states, while open C7 markers denote 20 accepted stationary states whose stability was not assessed. Connecting segments only guide the eye between saved states; the unequal windows and localized support do not imply convergence or physical crack propagation.'),
 dict(id='fig09',slug='stationarity_and_stability_evidence',title='Stationarity and stability require distinct evidence',message='All 15 C5 audited states are stable; C7 stationarity alone does not classify stability.',sources=[S5,S7,V+C5+'provenance/PREDECLARED_CONFIG.json',V+'pfpd_at1_petsc_vi_solver_v1/provenance/PREDECLARED_CONFIG.json',V+C7+'provenance/PREDECLARED_CONFIG.json'],plot_type='Dimensionless curvature and tolerance-normalized residuals',clot_relevance='Prevents solver convergence from being mislabeled as a fracture event.',caption='The C5 mechanical and condensed phase curvatures are shown with the archived curvature threshold, alongside force and projected phase KKT residuals normalized by their acceptance tolerances. All 15 C5 audited states are classified as stationary and stable; the intact state has no movable phase block, and its Schur value is therefore absent. C7 residuals establish stationarity of the 20 accepted states, but no C7 stability calculation exists. No instability was identified in the C5 audited window; this is not a statement about every intervening state or later loads.'),
 dict(id='fig10',slug='implications_for_clot_simulation',title='Implications for future clot simulation',message='Mechanical consistency, a physical failure observable and clot calibration remain separate requirements.',sources=[ONSET,S5,S7,V+B+'SUMMARY.json',V+A+'SUMMARY.json'],plot_type='Evidence / interpretation limit / development implication matrix',clot_relevance='Explicitly states what the current evidence permits and what remains to be established.',caption='The current numerical evidence is mapped to interpretation limits and development implications for a future clot model. Activation fractions depend on bond sampling, positive-phase states need not be unstable, and finite-domain loading consistency remains unresolved. These findings justify careful validation of boundary loading and failure observables before interpreting simulated phase as clot rupture. The diagram summarizes development implications only; no clot-specific calibration, biological mechanism or patient-level prediction is claimed.')
]

def write_plan(folder):
 import json
 lines=['# Figure plan','', 'All numeric values will be loaded from the listed existing files. No solver or new scientific experiment is invoked.','', '| ID | Title | Scientific message | Type | Clot relevance |','|---|---|---|---|---|']
 for s in SPECS:lines.append('| '+ ' | '.join(s[k] for k in ['id','title','message','plot_type','clot_relevance'])+' |')
 lines += ['','## Exact sources']
 for s in SPECS:lines += ['',f'### {s["id"]} — {s["title"]}','']+['- `'+x+'`' for x in s['sources']]
 lines += ['','## Exclusions and interpretation decisions','','- C3 activation is not pooled with C5/C7: earlier geometry/model and loading differences preclude a controlled convergence plot.','- L050/L075 have affine mechanics data only; no activation or fracture values are inferred.','- No C7 curvature or instability interval is plotted: stability is unassessed.','- No unstable mode, rupture morphology, calibrated clot-failure metric or patient result is fabricated.','- “Artifact-consistent” denotes a possible interpretation; the latest root cause remains INCONCLUSIVE.','- No interpolation, smoothing, fitted curves or resampling is used. Lines between saved points are visual guides.','- The optional timing/performance figure is omitted: it would distract from the scientific evidence.']
 (folder/'FIGURE_PLAN.md').write_text('\n'.join(lines)+'\n')
 (folder/'output/manifests/figure_plan.json').write_text(json.dumps(SPECS,indent=2)+'\n')
# Explicit shared loader dependencies, including the archived stress records.
_ONSET_INPUTS=SPECS[1]['sources']
_BRANCH_INPUTS=SPECS[7]['sources']
for _spec in SPECS:
    _extra=[]
    if _spec['id'] in ('fig01','fig02','fig08','fig10'):_extra+=_ONSET_INPUTS
    if _spec['id'] in ('fig01','fig08','fig09','fig10'):_extra+=_BRANCH_INPUTS
    if _spec['id'] in ('fig01','fig03','fig04','fig05','fig06','fig07','fig10'):_extra+=BS
    if _spec['id'] in ('fig01','fig10'):_extra+=['../PROJECT_ACTIVE_CONTEXT.md']
    if _spec['id'] in ('fig08','fig09'):_extra+=['pd_clot/pfpd_candidate/coupling_stability_audit.py','pd_clot/pfpd_candidate/adr_adapter_at1.py']
    _spec['sources']=list(dict.fromkeys(_spec['sources']+_extra))
    _spec['caption']=_spec['caption'].replace('energy-weighted mean phase','quadrature-weighted mean phase')

if __name__=='__main__':
 from pathlib import Path
 write_plan(Path(__file__).resolve().parent)
